//! IPC types of the approval window (S2-16). Display data only: ids, digests as hex, fixed
//! tokens and already-cleaned labels. Nothing here can create or authorise an approval.
//! TypeScript is generated by `ts-rs` into `apps/desktop/src/ipc/`.

use std::fmt;

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Sent only to the `approval` window: a new approval to show (payload [`ApprovalRequestDto`]).
pub const EVT_APPROVAL_REQUEST: &str = "approval:request";
/// Sent only to the `approval` window: an approval ended, close it ([`ApprovalClosedDto`]).
pub const EVT_APPROVAL_CLOSED: &str = "approval:closed";
/// The only window label that may answer approvals.
pub const APPROVAL_WINDOW: &str = "approval";

/// What an approval is for. `Submit` has its own title and colour.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum ApprovalKindDto {
    Plan,
    Step,
    Submit,
}

/// Tier badge. A step the policy refuses (Never) is a `refused` line, never a badge that runs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum ApprovalTierDto {
    Read,
    Reversible,
    Consequential,
}

/// The human's answer (`approval_respond`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum ApprovalDecisionDto {
    Approve,
    Deny,
}

/// How an approval ended.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub enum ApprovalOutcomeDto {
    Approved,
    Denied,
    Expired,
    Killed,
}

/// One step of a plan (or the single action of a step approval).
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ApprovalLineDto {
    pub index: u16,
    /// Fixed operation token (`click`, `type`, ...).
    pub op: String,
    /// Cleaned label (inert text, at most 60 characters).
    pub target: Option<String>,
    /// Cleaned exact text of a `type` step.
    pub text: Option<String>,
    pub tier: ApprovalTierDto,
    pub refused: bool,
    pub ask_again: bool,
}

impl fmt::Debug for ApprovalLineDto {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ApprovalLineDto")
            .field("index", &self.index)
            .field("op", &self.op)
            .field("tier", &self.tier)
            .field("refused", &self.refused)
            .finish_non_exhaustive()
    }
}

/// Event `approval:request` and the result of `approval_ready`.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ApprovalRequestDto {
    /// Random single-use id (32 hex digits).
    pub id: String,
    pub kind: ApprovalKindDto,
    /// Full lowercase hex digest the window must echo back in `approval_respond`.
    pub digest_hex: String,
    /// Fixed-format one-liner built from typed data.
    pub summary: String,
    pub lines: Vec<ApprovalLineDto>,
    /// `false` = dry run / observe only, `true` = this would really act.
    pub live: bool,
    /// The step changed since the plan was approved.
    pub changed: bool,
    /// Seconds until the request expires.
    pub timeout_secs: u32,
}

impl fmt::Debug for ApprovalRequestDto {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ApprovalRequestDto")
            .field("kind", &self.kind)
            .field("lines", &self.lines.len())
            .field("live", &self.live)
            .finish_non_exhaustive()
    }
}

/// Event `approval:closed`: remove this approval from the window.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ApprovalClosedDto {
    pub id: String,
    pub outcome: ApprovalOutcomeDto,
}
